(()=>{'use strict';const panels=[...document.querySelectorAll('.page-panel')];const pageLinks=[...document.querySelectorAll('.site-header nav a,.page-dots a')];let current='home';function setCurrent(id){current=id;pageLinks.forEach(link=>{const selected=link.getAttribute('href')==='#'+id;if(selected)link.setAttribute('aria-current',link.closest('.page-dots')?'true':'page');else link.removeAttribute('aria-current');});}const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting&&entry.intersectionRatio>=.5)setCurrent(entry.target.id);},{threshold:[.5,.65]});panels.forEach(panel=>observer.observe(panel));const toggle=document.querySelector('#color-toggle');function setColor(color,save){document.documentElement.dataset.color=color;const dark=color==='dark';toggle.setAttribute('aria-pressed',String(dark));toggle.setAttribute('aria-label',dark?'切换到日间模式':'切换到夜间模式');document.querySelector('meta[name="theme-color"]').content=dark?'#151b22':'#ffffff';if(save)try{localStorage.setItem('personal-space-color',color);}catch{}}let color='light';try{color=localStorage.getItem('personal-space-color')==='dark'?'dark':'light';}catch{}setColor(color,false);toggle.addEventListener('click',()=>setColor(document.documentElement.dataset.color==='dark'?'light':'dark',true));document.addEventListener('keydown',event=>{const node=event.target;const editing=node instanceof HTMLElement&&(node.matches('input,textarea,select')||node.isContentEditable);if(editing||document.querySelector('dialog[open]'))return;let direction=0;if(event.key==='PageDown')direction=1;if(event.key==='PageUp')direction=-1;if(direction){event.preventDefault();const index=panels.findIndex(panel=>panel.id===current);const next=panels[Math.max(0,Math.min(panels.length-1,index+direction))];next.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});})();
